"use client";

import { startTransition, useEffect, useState } from "react";
import { apiRequest } from "@/compartido/lib/api";
import type { AdminTrashedUserPreview, AdminUserCreateInput, AdminUserMutationInput, AdminUserPreview } from "@/compartido/types/admin";

type AdminUsersResponse = {
  ok: boolean;
  users?: AdminUserPreview[];
  trashedUsers?: AdminTrashedUserPreview[];
  message?: string;
};

export function useAdminUsers(enabled: boolean, refreshIntervalMs = 0) {
  const [users, setUsers] = useState<AdminUserPreview[]>([]);
  const [trashedUsers, setTrashedUsers] = useState<AdminTrashedUserPreview[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [lastUpdatedAt, setLastUpdatedAt] = useState<string | null>(null);
  const [refreshTick, setRefreshTick] = useState(0);

  useEffect(() => {
    let cancelled = false;

    const run = async () => {
      if (!enabled) {
        startTransition(() => setUsers([]));
        startTransition(() => setTrashedUsers([]));
        setLastUpdatedAt(null);
        return;
      }

      setIsLoading(true);
      const response = await apiRequest<AdminUsersResponse>("/api/admin/users");
      if (!cancelled && response.ok) {
        startTransition(() => setUsers(response.data?.users ?? []));
        startTransition(() => setTrashedUsers(response.data?.trashedUsers ?? []));
        setLastUpdatedAt(new Date().toISOString());
      }
      if (!cancelled) {
        setIsLoading(false);
      }
    };

    void run();
    const intervalId =
      enabled && refreshIntervalMs > 0
        ? window.setInterval(() => {
            void run();
          }, refreshIntervalMs)
        : null;

    return () => {
      cancelled = true;
      if (intervalId) {
        window.clearInterval(intervalId);
      }
    };
  }, [enabled, refreshIntervalMs, refreshTick]);

  const refreshUsers = () => {
    setRefreshTick((current) => current + 1);
  };

  const updateUser = async (payload: AdminUserMutationInput) => {
    const response = await apiRequest<AdminUsersResponse>("/api/admin/users", {
      method: "PATCH",
      body: JSON.stringify(payload),
    });

    if (response.ok) {
      setUsers(response.data?.users ?? []);
      setTrashedUsers(response.data?.trashedUsers ?? []);
      setLastUpdatedAt(new Date().toISOString());
      return true;
    }

    return response.data?.message ?? false;
  };

  const createUser = async (payload: AdminUserCreateInput) => {
    const response = await apiRequest<AdminUsersResponse>("/api/admin/users", {
      method: "POST",
      body: JSON.stringify(payload),
    });

    if (response.ok) {
      setUsers(response.data?.users ?? []);
      setTrashedUsers(response.data?.trashedUsers ?? []);
      setLastUpdatedAt(new Date().toISOString());
      return true;
    }

    return response.data?.message ?? false;
  };

  const deleteUser = async (payload:
    | { action: "trash"; userId: string; justification: string; confirmed: boolean; secondConfirmed: boolean }
    | { action: "recover" | "purge"; trashId: string; confirmed: boolean; secondConfirmed: boolean }
    | { userId: string; expectedName: string }
  ) => {
    const requestPayload = "expectedName" in payload
      ? {
          action: "trash" as const,
          userId: payload.userId,
          justification: "Borrado administrativo solicitado desde el panel de empresas con confirmación heredada del nombre.",
          confirmed: true,
          secondConfirmed: true,
        }
      : payload;
    const response = await apiRequest<AdminUsersResponse>("/api/admin/users", {
      method: "DELETE",
      body: JSON.stringify(requestPayload),
    });

    if (response.ok) {
      setUsers(response.data?.users ?? []);
      setTrashedUsers(response.data?.trashedUsers ?? []);
      setLastUpdatedAt(new Date().toISOString());
      return true;
    }

    return response.data?.message ?? false;
  };

  return {
    users,
    trashedUsers,
    isLoading,
    lastUpdatedAt,
    refreshUsers,
    createAdminUser: createUser,
    updateAdminUser: updateUser,
    deleteAdminUser: deleteUser,
  };
}
