"use client";

import { useState } from "react";
import { Activity, ShieldCheck, Users } from "lucide-react";
import { RoleRouteGuard } from "@/compartido/components/role/role-route-guard";
import { useAuthUser } from "@/compartido/hooks/use-auth-user";
import { useVacancyTheme } from "@/compartido/theme/use-vacancy-theme";
import { AdminDashboardShell } from "@/frontend/admin/components/system/admin-dashboard-shell";
import { useAdminConsole } from "@/frontend/admin/hooks/use-admin-console";
import { useAdminUsers } from "@/frontend/admin/hooks/use-admin-users";
import {
  AdminSectionHeading,
  AdminSimpleTable,
  AdminStatCard,
  AdminSurface,
} from "@/frontend/admin/components/system/admin-dashboard-kit";

export default function AdminAuthPage() {
  const { isDark, toggleTheme } = useVacancyTheme();
  const { authUser } = useAuthUser();
  const enabled = authUser?.role === "admin";
  const { consoleData } = useAdminConsole(enabled);
  const { users, updateAdminUser } = useAdminUsers(enabled);
  const [notice, setNotice] = useState<string | null>(null);

  return (
    <RoleRouteGuard allowedRole="admin">
      <AdminDashboardShell isDark={isDark} onToggleTheme={toggleTheme} title="Auth" description="Session visibility, verification queue, and trust operations.">
        {notice ? (
          <div className={isDark ? "rounded-2xl border border-cyan-300/18 bg-cyan-300/8 px-4 py-3 text-sm text-cyan-100" : "rounded-2xl border border-sky-300 bg-sky-50 px-4 py-3 text-sm text-sky-700"}>
            {notice}
          </div>
        ) : null}

        <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          <AdminStatCard isDark={isDark} icon={ShieldCheck} label="Active Sessions" value={consoleData?.metrics.activeSessionsTotal ?? 0} />
          <AdminStatCard isDark={isDark} icon={Activity} label="Pending Verification" value={consoleData?.metrics.verificationPendingTotal ?? 0} />
          <AdminStatCard isDark={isDark} icon={Users} label="Admins" value={consoleData?.metrics.adminsTotal ?? 0} />
        </section>

        <section className="grid gap-5 xl:grid-cols-2">
          <AdminSurface isDark={isDark}>
            <AdminSectionHeading isDark={isDark} title="Recent Sessions" description="Latest authenticated sessions across the platform." />
            <div className="mt-5 space-y-3">
              {(consoleData?.sessions ?? []).map((session) => (
                <div key={`${session.userId}-${session.createdAt}`} className={isDark ? "rounded-2xl border border-white/8 bg-white/[0.04] p-4" : "rounded-2xl border border-slate-200 bg-slate-50 p-4"}>
                  <p className={isDark ? "font-semibold text-white" : "font-semibold text-slate-950"}>{session.displayName}</p>
                  <p className={isDark ? "mt-1 text-sm text-slate-400" : "mt-1 text-sm text-slate-600"}>{session.role} · expires {new Date(session.expiresAt).toLocaleString("es-CO")}</p>
                </div>
              ))}
            </div>
          </AdminSurface>

          <AdminSurface isDark={isDark}>
            <AdminSectionHeading isDark={isDark} title="Verification Queue" description="Profiles waiting for review and trust approval." />
            <div className="mt-5 space-y-3">
              {(consoleData?.verifications ?? []).map((item) => (
                <div key={item.id} className={isDark ? "rounded-2xl border border-white/8 bg-white/[0.04] p-4" : "rounded-2xl border border-slate-200 bg-slate-50 p-4"}>
                  <p className={isDark ? "font-semibold text-white" : "font-semibold text-slate-950"}>{item.role} · {item.status}</p>
                  <p className={isDark ? "mt-1 text-sm text-slate-400" : "mt-1 text-sm text-slate-600"}>{new Date(item.submittedAt).toLocaleString("es-CO")}</p>
                </div>
              ))}
            </div>
          </AdminSurface>
        </section>

        <AdminSurface isDark={isDark}>
          <AdminSectionHeading isDark={isDark} title="Credentials Manager" description="Update email and password without leaving the admin console." />
          <div className="mt-5">
            <AdminSimpleTable isDark={isDark}>
              <table className="w-full min-w-[920px] text-sm">
                <thead className={isDark ? "border-b border-white/8 bg-white/[0.03] text-slate-400" : "border-b border-slate-200 bg-slate-50 text-slate-500"}>
                  <tr>
                    <th className="px-4 py-3 text-left font-medium">User</th>
                    <th className="px-4 py-3 text-left font-medium">Role</th>
                    <th className="px-4 py-3 text-left font-medium">Email</th>
                    <th className="px-4 py-3 text-left font-medium">Password</th>
                  </tr>
                </thead>
                <tbody>
                  {users.map((user) => (
                    <tr key={user.id} className={isDark ? "border-b border-white/6 last:border-b-0" : "border-b border-slate-100 last:border-b-0"}>
                      <td className="px-4 py-4 align-top">
                        <p className={isDark ? "font-medium text-white" : "font-medium text-slate-950"}>{user.nombre}</p>
                      </td>
                      <td className="px-4 py-4 align-top">{user.role}</td>
                      <td className="px-4 py-4 align-top">
                        <input
                          defaultValue={user.email}
                          onBlur={async (event) => {
                            const result = await updateAdminUser({ userId: user.id, email: event.target.value });
                            setNotice(result === true ? `Correo actualizado para ${user.nombre}.` : typeof result === "string" ? result : "No se pudo actualizar el correo.");
                          }}
                          className="w-full rounded-2xl border border-slate-300 bg-white px-4 py-2.5 text-sm text-slate-900 outline-none"
                        />
                      </td>
                      <td className="px-4 py-4 align-top">
                        <input
                          type="password"
                          placeholder="Nueva contraseña"
                          onBlur={async (event) => {
                            if (!event.target.value.trim()) {
                              return;
                            }
                            const result = await updateAdminUser({ userId: user.id, password: event.target.value });
                            event.target.value = "";
                            setNotice(result === true ? `Contrasena actualizada para ${user.nombre}.` : typeof result === "string" ? result : "No se pudo actualizar la contrasena.");
                          }}
                          className="w-full rounded-2xl border border-slate-300 bg-white px-4 py-2.5 text-sm text-slate-900 outline-none"
                        />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </AdminSimpleTable>
          </div>
        </AdminSurface>
      </AdminDashboardShell>
    </RoleRouteGuard>
  );
}
